import {LOCAL_AI_MAX_OUTPUT_TOKENS} from '../electron/shared/local-ai'
defineProps<{standalone?:boolean}>()
const studio=useLocalAiStudio()
const chat=reactive(studio)
watch(studio.tab,value=>{if(value==='chat')studio.tab.value='agent'})
const {tab,ready,error,busy,drawer,parameters,data,settings,apiKey,hfToken,connection,connecting,input,model,systemPrompt,query,format,sort,searching,results,selected,filesBusy,fileFilter,ggufOnly,modelFilter,showMissing,enqueueBusy,sending,downloads,runtime,hardware,activeDownloads,totalSize,localModels,serverModels,statusText,online,bytes,count,percent,downloadLabel,fit,refreshModels,saveSettings,clearKey,connect,usePreset,search,selectRepo,enqueue,downloadAction,importModels,removeModel,startModel,stopModel,chooseDirectory,chooseRuntime,copy,reveal,openLink,catalogSource,catalogUpdatedAt,catalogError,catalogLabel,details,detailsError,readme,readmeBusy,readmeError,loadReadme,selectedFileName,downloadChoices,selectedDownload,downloadSize,downloadParts,modelFormats,parameterLabel,dateLabel}=studio
