const pageTitle=computed(()=>navigation.find(item=>item.id===tab.value)?.label||'本地 AI')
const memoryPercent=computed(()=>hardware.value?Math.round((1-hardware.value.freeMemory/hardware.value.totalMemory)*100):0)
</script>

<template>
